<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <iostream>
#include <queue>
using namespace std;
char a[20][20],b[20][20];
queue <pair <int,int> > q;
int Dis[20][20],dis[11][11][11][11];
int fx[5]={-1,1,0,0},fy[5]={0,0,-1,1};
struct edge
{
	int u,v,fl,c,n;
}e[200005];
int cnt,head[505],p[505],v[505],s=501,t=502,ans,n,m,dep[505];
inline void add(int u,int v,int w)
{
//	cout << u << " " << v << " " << w << "\n";
	e[++cnt]={u,v,0,w,head[u]};
	head[u]=cnt;
	e[++cnt]={v,u,0,0,head[v]};
	head[v]=cnt;
}
inline bool Find()
{
	queue <int> q;
	for(int i=0;i<=t;i++)
		v[i]=dep[i]=0;
	q.push(s);
	v[s]=1;
	dep[s]=1;
	while(!q.empty())
	{
		int x=q.front();
		q.pop();
		for(int i=head[x];i;i=e[i].n)
		{
			if(!v[e[i].v]&&e[i].fl<e[i].c)
			{
				p[e[i].v]=i;
				q.push(e[i].v);
				v[e[i].v]=1;
				dep[e[i].v]=dep[x]+1;
				if(e[i].v==t)
					return 1;
			}
		}
	}
	return 0;
}
inline int dfs(int x,int now)
{
	if(x==t||!now)
		return now;
	int t=now;
	for(int i=head[x];i;i=e[i].n)
	{
		if(e[i].c>e[i].fl&&dep[e[i].v]==dep[x]+1)
		{
            int delta=dfs(e[i].v,min(t,e[i].c-e[i].fl));
			if(!delta)
				dep[e[i].v]=0;
            e[i].fl+=delta;
            e[((i-1)^1)+1].fl-=delta;
            t-=delta;
            if(t==0)
				break;
        }
	}
	return now-t;
}
inline void dinic()
{
	while(Find())
		ans+=dfs(s,1000000007);
}
int main(int argc, char** argv) {
	int n,t;
	cin >> n >> t;
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=n;j++)
		{
			Dis[i][j]=10000;
			cin >> a[i][j];
			if(a[i][j]=='Z')
				q.push({i,j}),Dis[i][j]=0;
			if(a[i][j]<='9') add(s,(i-1)*n+j,a[i][j]-'0');
		}
	}
	while(!q.empty())
	{
		int x=q.front().first,y=q.front().second;
		q.pop();
		for(int i=0;i<4;i++)
		{
			int nx=x+fx[i],ny=y+fy[i];
			if(nx>0&&ny>0&&nx<=n&&ny<=n&&a[nx][ny]<='9'&&Dis[nx][ny]>Dis[x][y]+1)
				Dis[nx][ny]=Dis[x][y]+1,q.push({nx,ny}); 
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=n;j++)
		{
			if(a[i][j]>'9') continue;
			for(int k=1;k<=n;k++)
				for(int l=1;l<=n;l++)
					dis[i][j][k][l]=10000;
			q.push({i,j});
			dis[i][j][i][j]=0;
			while(!q.empty())
			{
				int x=q.front().first,y=q.front().second;
				q.pop();
				for(int f=0;f<4;f++)
				{
					int nx=x+fx[f],ny=y+fy[f];
					if(nx>0&&ny>0&&nx<=n&&ny<=n&&a[nx][ny]<='9'&&dis[i][j][nx][ny]>dis[i][j][x][y]+1&&dis[i][j][x][y]<Dis[x][y])
					{
						dis[i][j][nx][ny]=dis[i][j][x][y]+1;
							q.push({nx,ny});
					}
				}
			}
			for(int k=1;k<=n;k++)
				for(int l=1;l<=n;l++)
					if(dis[i][j][k][l]<=min(Dis[k][l],t))
						add((i-1)*n+j,(k-1)*n+l+100,10000);
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=n;j++)
		{
			cin >> b[i][j];
			if(b[i][j]<='9') add((i-1)*n+j+100,502,b[i][j]-'0');
		}
	}
	dinic();
	cout << ans;
	return 0;
}
